//! The dataset: the maps by kind, the `meta` with provenance and counts, the JSON
//! embedded in the binary. Crosses the IPC as-is: camelCase everywhere.

use std::collections::BTreeMap;
use std::fmt;
#[cfg(feature = "embedded")]
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

use crate::{Diagnostics, Entry, Target};

/// The version of the JSON shape. Changes whenever a dataset struct changes, so a file
/// generated by another version of the crate is rejected instead of being read half-broken.
pub const SCHEMA_VERSION: u32 = 3;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Meta {
    pub schema_version: u32,
    /// The most recent timestamp among the snapshot's pages.
    pub snapshot_at: String,
    pub max_revid: u64,
    /// The latest game patch the wiki knows about: says how up to date the text is.
    pub last_known_patch: Option<Patch>,
    pub source: Source,
    pub counts: Counts,
    pub diagnostics: Diagnostics,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Patch {
    pub number: String,
    pub date: String,
}

/// Provenance and license: the dataset is derived from the wiki and travels with attribution.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Source {
    pub name: String,
    pub url: String,
    pub license: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Counts {
    pub items: u32,
    pub trinkets: u32,
    pub achievements: u32,
    pub bosses: u32,
    pub challenges: u32,
    pub characters: u32,
    pub transformations: u32,
}

/// Entries by kind, indexed the way the game knows them. Bosses by their bestiary triple
/// (`Dataset::boss_key`), since a JSON key is a string.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Dataset {
    pub meta: Meta,
    pub items: BTreeMap<u32, Entry>,
    pub trinkets: BTreeMap<u32, Entry>,
    pub achievements: BTreeMap<u32, Entry>,
    pub bosses: BTreeMap<String, Entry>,
    pub challenges: BTreeMap<u32, Entry>,
    pub characters: BTreeMap<u32, Entry>,
    pub transformations: BTreeMap<u32, Entry>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DatasetError {
    /// The file is from another version of the crate: it is not read half-broken.
    SchemaMismatch {
        found: u32,
        expected: u32,
    },
    Malformed {
        reason: String,
    },
}

impl fmt::Display for DatasetError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DatasetError::SchemaMismatch { found, expected } => {
                write!(f, "dataset schema {found}, expected {expected}")
            }
            DatasetError::Malformed { reason } => write!(f, "invalid dataset: {reason}"),
        }
    }
}

impl std::error::Error for DatasetError {}

/// Just the schema version: read before the rest, so a file from another version gives
/// `SchemaMismatch` instead of a shape error on some random field.
#[derive(Deserialize)]
struct Head {
    meta: HeadMeta,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct HeadMeta {
    schema_version: u32,
}

#[cfg(feature = "embedded")]
static EMBEDDED: OnceLock<Result<Dataset, DatasetError>> = OnceLock::new();

impl Dataset {
    /// A dataset with no entries, with the current schema and the rest of `meta` empty:
    /// the starting point of `build`.
    pub(crate) fn empty() -> Dataset {
        Dataset {
            meta: Meta {
                schema_version: SCHEMA_VERSION,
                snapshot_at: String::new(),
                max_revid: 0,
                last_known_patch: None,
                source: Source {
                    name: String::new(),
                    url: String::new(),
                    license: String::new(),
                },
                counts: Counts {
                    items: 0,
                    trinkets: 0,
                    achievements: 0,
                    bosses: 0,
                    challenges: 0,
                    characters: 0,
                    transformations: 0,
                },
                diagnostics: Diagnostics::default(),
            },
            items: BTreeMap::new(),
            trinkets: BTreeMap::new(),
            achievements: BTreeMap::new(),
            bosses: BTreeMap::new(),
            challenges: BTreeMap::new(),
            characters: BTreeMap::new(),
            transformations: BTreeMap::new(),
        }
    }

    /// The boss key: the game's `id.variant.subtype` notation.
    pub fn boss_key(id: u32, variant: u32, subtype: u32) -> String {
        format!("{id}.{variant}.{subtype}")
    }

    /// The entry under `key` in the collection `wiki.json` calls `collection`: how
    /// `corrections.json` names one, since the file is written against the JSON.
    pub(crate) fn entry_by_key_mut(&mut self, collection: &str, key: &str) -> Option<&mut Entry> {
        fn by_number<'a>(map: &'a mut BTreeMap<u32, Entry>, key: &str) -> Option<&'a mut Entry> {
            map.get_mut(&key.parse::<u32>().ok()?)
        }
        match collection {
            "items" => by_number(&mut self.items, key),
            "trinkets" => by_number(&mut self.trinkets, key),
            "achievements" => by_number(&mut self.achievements, key),
            "bosses" => self.bosses.get_mut(key),
            "challenges" => by_number(&mut self.challenges, key),
            "characters" => by_number(&mut self.characters, key),
            "transformations" => by_number(&mut self.transformations, key),
            _ => None, // allowed: a name from a hand-written file, an open-ended string
        }
    }

    /// Whether [`Dataset::entry_by_key_mut`] would find an entry.
    pub fn has_key(&self, collection: &str, key: &str) -> bool {
        let by_number = |map: &BTreeMap<u32, Entry>| {
            key.parse::<u32>()
                .ok()
                .is_some_and(|n| map.contains_key(&n))
        };
        match collection {
            "items" => by_number(&self.items),
            "trinkets" => by_number(&self.trinkets),
            "achievements" => by_number(&self.achievements),
            "bosses" => self.bosses.contains_key(key),
            "challenges" => by_number(&self.challenges),
            "characters" => by_number(&self.characters),
            "transformations" => by_number(&self.transformations),
            _ => false, // allowed: a name from a hand-written file, an open-ended string
        }
    }

    /// The entry for a `Target`, if the dataset has one. Floors, rooms and pickups have no
    /// page in the dataset: `None` by construction. Transformations used to be in that
    /// group and are not any more — they have sixteen pages of their own.
    pub fn entry(&self, t: &Target) -> Option<&Entry> {
        match t {
            Target::Item { id } => self.items.get(id),
            Target::Trinket { id } => self.trinkets.get(id),
            Target::Achievement { id } => self.achievements.get(id),
            Target::Challenge { number } => self.challenges.get(number),
            Target::Character { id } => self.characters.get(id),
            Target::Entity {
                id,
                variant,
                subtype,
            } => self.bosses.get(&Self::boss_key(*id, *variant, *subtype)),
            Target::Transformation { id } => self.transformations.get(id),
            Target::Stage { .. } | Target::Room { .. } | Target::Concept { .. } => None,
        }
    }

    /// The dataset compiled into the binary: `dataset/wiki.json` compressed by `build.rs`,
    /// inflated and read once. Only with the `embedded` feature (on by default).
    #[cfg(feature = "embedded")]
    pub fn embedded() -> Result<&'static Dataset, &'static DatasetError> {
        EMBEDDED.get_or_init(Dataset::inflate_embedded).as_ref()
    }

    #[cfg(feature = "embedded")]
    fn inflate_embedded() -> Result<Dataset, DatasetError> {
        let deflated: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/wiki.json.deflate"));
        let bytes = miniz_oxide::inflate::decompress_to_vec(deflated).map_err(|e| {
            DatasetError::Malformed {
                reason: format!("embedded blob does not inflate: {e}"),
            }
        })?;
        let text = String::from_utf8(bytes).map_err(|e| DatasetError::Malformed {
            reason: format!("embedded blob is not UTF-8: {e}"),
        })?;
        Dataset::from_json(&text)
    }

    pub fn from_json(s: &str) -> Result<Dataset, DatasetError> {
        let malformed = |e: serde_json::Error| DatasetError::Malformed {
            reason: e.to_string(),
        };
        let head: Head = serde_json::from_str(s).map_err(malformed)?;
        if head.meta.schema_version != SCHEMA_VERSION {
            return Err(DatasetError::SchemaMismatch {
                found: head.meta.schema_version,
                expected: SCHEMA_VERSION,
            });
        }
        serde_json::from_str(s).map_err(malformed)
    }

    /// Readable JSON, with a trailing newline: this is the file that ends up in the repo.
    pub fn to_json(&self) -> String {
        // In-memory data, of our own types, with map keys that serde_json knows how to
        // write (integers and strings): serialization has no way to fail, and the `Err`
        // branch is dead. The empty default is there only to avoid an `unwrap` in the crate.
        let mut s = serde_json::to_string_pretty(self).unwrap_or_default();
        s.push('\n');
        s
    }
}

#[cfg(all(test, feature = "embedded"))]
mod tests {
    use super::*;

    #[test]
    fn embedded_loads() {
        let ds = Dataset::embedded().expect("valid embedded dataset");
        assert_eq!(ds.meta.schema_version, SCHEMA_VERSION);
        assert_eq!(ds.meta.counts.trinkets, 188);
    }
}
